    function resolveQuestionTextarea(context={}){ const direct=[context.textarea,context.targetTextarea,context.activeTextarea,context.field,lastExternalTextarea]; try{direct.push(window.QmxDiagramLauncher?.getActiveTextarea?.());}catch(error){} for(const textarea of direct){if(isUsableTextarea(textarea))return textarea;} const active=document.activeElement;if(isUsableTextarea(active))return active; const candidates=visibleTextareaCandidates(); const scored=candidates.map((textarea)=>{const marker=`${textarea.name||''} ${textarea.id||''} ${textarea.dataset?.field||''} ${textarea.getAttribute('aria-label')||''}`.toLowerCase();let score=0;if(/question|stem|prompt|creative|cq|part/.test(marker))score+=8;if(/answer|solution/.test(marker))score-=2;if(textarea.value?.includes('[[qmx-diagram:'))score+=1;return{textarea,score};}).sort((a,b)=>b.score-a.score); return scored[0]?.textarea||null; }
