    function createDocument(){ return { version:40,id:uid('oceanography-diagram'),mode:'oceanography-diagram',title:'Oceanography / Marine Science & Coastal Processes Diagram',width:1180,height:720,background:'#ffffff',gridSize:20,oceanographyShowGrid:false,oceanographyShowLabels:true,oceanographyShowEnergy:true,oceanographyShowZones:true,oceanographyShowTrophicLevels:true,snap:true,objects:[] }; }
