    function defaultSize(kind){ return ({ocean:[300,170],coastline:[250,120],beach:[230,100],'sea-cliff':[170,160],wave:[220,100],tide:[170,110],'surface-current':[230,90],'deep-current':[230,90],gyre:[180,160],upwelling:[160,150],downwelling:[160,150],'coral-reef':[240,150],mangrove:[220,150],estuary:[250,140],lagoon:[240,140],'continental-shelf':[300,100],'continental-slope':[280,130],'abyssal-plain':[320,100],'mid-ocean-ridge':[280,160],'ocean-trench':[260,160],seamount:[180,170],'submarine-canyon':[260,140],'mixed-layer':[300,90],thermocline:[300,80],halocline:[300,80],'research-vessel':[190,110],buoy:[100,140]})[kind]||[180,110]; }
    function makeNode(kind='ocean',overrides={}){ const [fill,stroke]=nodeStyle(kind),[width,height]=defaultSize(kind); const levels={ocean:0,coastline:0,beach:0,'sea-cliff':0,wave:0,tide:0,'surface-current':1,'deep-current':3,gyre:1,upwelling:2,downwelling:2,'coral-reef':1,mangrove:0,estuary:0,lagoon:0,'continental-shelf':1,'continental-slope':2,'abyssal-plain':4,'mid-ocean-ridge':3,'ocean-trench':5,seamount:3,'submarine-canyon':2,'mixed-layer':1,thermocline:2,halocline:2,'research-vessel':0,buoy:0}; return{id:uid('oceanography-node'),type:'oceanography-node',kind,x:440,y:260,width,height,label:kind.replace(/-/g,' '),fill,stroke,textColor:'#0f172a',lineWidth:2.5,rotation:0,trophicLevel:levels[kind]??0,energy:0,population:0,...overrides}; }
