    function makePyramid(kind='wave-profile',overrides={}){ const titles={'wave-profile':'Wave Profile','tide-graph':'Tidal Cycle','depth-profile':'Ocean Basin Depth Profile'}; const levels=kind==='tide-graph'?'00:00|1.2\n03:00|2.8\n06:00|4.5\n09:00|2.6\n12:00|1.0\n15:00|2.7\n18:00|4.6\n21:00|2.5\n24:00|1.2':kind==='depth-profile'?'Coast|0\nShelf edge|-200\nContinental slope|-2500\nAbyssal plain|-4500\nMid-ocean ridge|-2500\nOcean trench|-8000':'0 m|0\n20 m|2.5\n40 m|5.0\n60 m|2.5\n80 m|0\n100 m|-2.5\n120 m|-5.0';return{id:uid('oceanography-pyramid'),type:'oceanography-pyramid',kind,x:320,y:90,width:540,height:560,title:titles[kind]||'Oceanography chart',levels,unit:kind==='tide-graph'?'m':kind==='depth-profile'?'m':'m',fill:'#dbeafe',stroke:'#0369a1',textColor:'#0c4a6e',lineWidth:2.5,...overrides}; }
    function makeLink(sourceId='',sourcePort='e',targetId='',targetPort='w',overrides={}){ return{id:uid('oceanography-link'),type:'oceanography-link',sourceId,sourcePort,targetId,targetPort,x1:300,y1:300,x2:650,y2:300,kind:'surface-current',label:'ocean current',stroke:'#0284c7',textColor:'#075985',lineWidth:3,dashed:false,showArrow:true,energy:0,...overrides}; }
