    function setObjects(objects){state.document.objects=objects;state.selectedId=null;state.labelStart=null;state.linkStart=null;pushHistory();render();}
    function addNode(kind,x,y,overrides={}){const o=makeNode(kind,{x,y,...overrides});state.document.objects.push(o);return o;}
