    function buildEditor(){if(state.root)return;addStyles();const root=document.createElement('div');root.className='qmx-oceanography-editor';root.hidden=true;root.innerHTML=`<div class="qmx-oceanography-shell" role="dialog" aria-modal="true" aria-label="Oceanography, marine science and coastal processes diagram editor"><header class="qmx-oceanography-header"><div><div class="qmx-oceanography-title">Oceanography / Marine Science & Coastal Processes Diagram</div><div class="qmx-oceanography-subtitle">Ocean basins, waves, tides, currents, coastal landforms, marine ecosystems and seafloor relief</div></div><div class="qmx-oceanography-actions"><button class="qmx-oceanography-btn" data-oceanography="new">New</button><button class="qmx-oceanography-btn" data-oceanography="undo">Undo</button><button class="qmx-oceanography-btn" data-oceanography="redo">Redo</button><button class="qmx-oceanography-btn" data-oceanography="duplicate">Duplicate</button><button class="qmx-oceanography-btn danger" data-oceanography="delete">Delete</button><button class="qmx-oceanography-btn" data-oceanography="close">×</button></div></header><main class="qmx-oceanography-main"><aside class="qmx-oceanography-panel"><strong>Oceanography tools</strong><div class="qmx-oceanography-tools" data-tools></div><div class="qmx-oceanography-section">Oceanography presets</div><div class="qmx-oceanography-presets"><button class="qmx-oceanography-preset" data-preset="ocean-basin">Ocean basin</button><button class="qmx-oceanography-preset" data-preset="coastal-processes">Coastal processes</button><button class="qmx-oceanography-preset" data-preset="wave-refraction">Wave refraction</button><button class="qmx-oceanography-preset" data-preset="tides">Tidal cycle</button><button class="qmx-oceanography-preset" data-preset="ocean-currents">Ocean currents</button><button class="qmx-oceanography-preset" data-preset="upwelling">Coastal upwelling</button><button class="qmx-oceanography-preset" data-preset="coral-reef">Coral reef</button><button class="qmx-oceanography-preset" data-preset="ocean-zonation">Ocean zonation</button><button class="qmx-oceanography-preset" data-preset="depth-profile">Depth profile</button><button class="qmx-oceanography-preset" data-preset="clear">Clear</button></div><p class="qmx-oceanography-subtitle">Smart link: click a source port and then a target port. Links remain attached when features move.</p></aside><section class="qmx-oceanography-canvas-wrap"><div class="qmx-oceanography-canvas" data-canvas></div></section><aside class="qmx-oceanography-panel"><strong>Document</strong><div class="qmx-oceanography-field"><label>Title</label><input data-doc="title"></div><div class="qmx-oceanography-grid2"><div class="qmx-oceanography-field"><label>Width</label><input type="number" min="600" max="2400" data-doc="width"></div><div class="qmx-oceanography-field"><label>Height</label><input type="number" min="400" max="1800" data-doc="height"></div><div class="qmx-oceanography-field"><label>Grid size</label><input type="number" min="5" max="100" data-doc="gridSize"></div><div class="qmx-oceanography-field"><label>Background</label><input type="color" data-doc="background"></div></div><label class="qmx-oceanography-check"><input type="checkbox" data-doc="oceanographyShowGrid"> Show grid</label><label class="qmx-oceanography-check"><input type="checkbox" data-doc="oceanographyShowLabels"> Show smart labels</label><label class="qmx-oceanography-check"><input type="checkbox" data-doc="oceanographyShowEnergy"> Show process values</label><label class="qmx-oceanography-check"><input type="checkbox" data-doc="oceanographyShowZones"> Show marine zones</label><label class="qmx-oceanography-check"><input type="checkbox" data-doc="oceanographyShowTrophicLevels"> Show depth levels</label><label class="qmx-oceanography-check"><input type="checkbox" data-doc="snap"> Snap to grid</label><hr><strong>Selected object</strong><div data-selected></div><div class="qmx-oceanography-summary" data-summary></div></aside></main><footer class="qmx-oceanography-footer"><div class="qmx-oceanography-status" data-status></div><div class="qmx-oceanography-actions"><button class="qmx-oceanography-btn" data-oceanography="export-svg">Export SVG</button><button class="qmx-oceanography-btn" data-oceanography="export-png">Export PNG</button><button class="qmx-oceanography-btn primary" data-oceanography="insert">Insert into question</button></div></footer></div>`;document.body.appendChild(root);state.root=root;state.canvas=root.querySelector('[data-canvas]');state.controls={tools:root.querySelector('[data-tools]'),selected:root.querySelector('[data-selected]'),summary:root.querySelector('[data-summary]'),status:root.querySelector('[data-status]'),undo:root.querySelector('[data-oceanography="undo"]'),redo:root.querySelector('[data-oceanography="redo"]')};TOOL_DEFS.forEach(([id,label,bn])=>{const b=document.createElement('button');b.className='qmx-oceanography-tool';b.dataset.tool=id;b.innerHTML=window.QmxDiagramToolButtonContent?window.QmxDiagramToolButtonContent(id,label,bn):`${esc(label)}<small>${esc(bn)}</small>`;state.controls.tools.appendChild(b);});root.addEventListener('click',onRootClick);root.addEventListener('change',onRootChange);state.canvas.addEventListener('pointerdown',onCanvasPointerDown);document.addEventListener('pointermove',onPointerMove,{passive:false});document.addEventListener('pointerup',onPointerUp);document.addEventListener('pointercancel',onPointerUp);document.addEventListener('focusin',(event)=>{if(isUsableTextarea(event.target))lastExternalTextarea=event.target;},true);document.addEventListener('keydown',onKeydown);}
    function open(context={}){buildEditor();state.context=context||{};state.sourceTextarea=resolveQuestionTextarea(state.context);state.document=state.context.initialSpec?Diagram.normalizeSpec(state.context.initialSpec):createDocument();if(state.document.mode!=='oceanography-diagram')state.document=createDocument();state.selectedId=null;state.activeTool='select';state.interaction=null;state.labelStart=null;state.linkStart=null;state.history=[];state.historyIndex=-1;pushHistory();syncDocumentControls();setTool('select',false);render();state.root.hidden=false;document.body.dataset.qmxOceanographyOverflow=document.body.style.overflow||'';document.body.style.overflow='hidden';setStatus(state.context.initialSpec?'Existing oceanography diagram loaded.':'Choose a oceanographic feature, smart ocean-current link, chart, label, process arrow or preset.');}
    function close(){if(!state.root)return;state.root.hidden=true;document.body.style.overflow=document.body.dataset.qmxOceanographyOverflow||'';delete document.body.dataset.qmxOceanographyOverflow;state.labelStart=null;state.linkStart=null;state.interaction=null;}
    function findTokenTextarea(token){return Array.from(document.querySelectorAll('textarea')).find((t)=>t.value.includes(token))||null;}
    function openFromPreview(figure){const payload=String(figure?.dataset.qmxDiagramPayload||'');if(!payload)return false;let spec;try{spec=Diagram.decodePayload(payload);}catch(error){return false;}if(spec.mode!=='oceanography-diagram')return false;const token=`[[qmx-diagram:${payload}]]`;const textarea=findTokenTextarea(token)||window.QmxDiagramLauncher?.getActiveTextarea?.();let replaceRange=null;if(textarea){const start=textarea.value.indexOf(token);if(start>=0)replaceRange={start,end:start+token.length};}open({tool:{id:'oceanography-diagram'},textarea,initialSpec:spec,replaceRange,editMode:true});return true;}
    function registerHandlers(){const launcher=window.QmxDiagramLauncher;if(!launcher?.registerToolHandler)return false;let registered=false;['oceanography-diagram','oceanography','marine-science','ocean-basin','coastal-processes','ocean-currents','tides','wave-refraction','upwelling','coral-reef'].forEach((id)=>{try{launcher.registerToolHandler(id,open);registered=true;}catch(error){}});return registered;}
    buildEditor();registerHandlers();document.addEventListener('qmx:diagram-launcher-ready',registerHandlers);
    window.QmxOceanographyEditor=Object.freeze({version:'1.0.0',open,close,openFromPreview});
